import{_ as a,o as n,c as t,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Syntax-Variants.md","filePath":"manual-en/Syntax-Variants.md","lastUpdated":1785684581000}'),s={name:"manual-en/Syntax-Variants.md"};function i(r,e,d,m,l,h){return n(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="_6-3-syntax-variants" tabindex="-1">6.3 Syntax Variants <a class="header-anchor" href="#_6-3-syntax-variants" aria-label="Permalink to &quot;6.3 Syntax Variants&quot;">​</a></h3><p>There are three variants of command syntax, which vary only in how they detect the end of one command and the start of the next.</p><p>In <em>interactive mode</em> , which is the default for syntax typed at a command prompt, a period as the last non-blank character on a line ends a command. A blank line also ends a command.</p><p>In <em>batch mode</em> , an end-of-line period or a blank line also ends a command. Additionally, it treats any line that has a non-blank character in the leftmost column as beginning a new command. Thus, in batch mode the second and subsequent lines in a command must be indented.</p><p>Regardless of the syntax mode, a plus sign, minus sign, or period in the leftmost column of a line is ignored and causes that line to begin a new command. This is most useful in batch mode, in which the first line of a new command could not otherwise be indented, but it is accepted regardless of syntax mode.</p><p>The default mode for reading commands from a file is <em>auto mode</em>. It is the same as batch mode, except that a line with a non-blank in the leftmost column only starts a new command if that line begins with the name of a PSPP command. This correctly interprets most valid PSPP syntax files regardless of the syntax mode for which they are intended.</p><p>The --interactive (or -i) or --batch (or -b) options set the syntax mode for files listed on the PSPP command line. See <a href="./Main-Options">Main Options</a>, for more details.</p>',7)])])}const p=a(s,[["render",i]]);export{f as __pageData,p as default};
